PQ(SPG, '2024T2', 92, 1, 'mcq', { fam: "g-teamtype",
  cs: ["team-basics"],
  week: 1,
  diff: "moderate",
  q: "<p>Match List 1 and List 2.</p><table class=\"t\"><tr><th>List 1</th><th>List 2</th></tr><tr><td>A. Cross-Functional Team</td><td>I. A team that uses technology to link physically dispersed members to achieve a common goal.</td></tr><tr><td>B. Virtual Team</td><td>II. A team of employees (typically 10 to 15 in number) who perform highly related or interdependent jobs; these teams take on some supervisory responsibilities.</td></tr><tr><td>C. Self-managed Team</td><td>III. A work team composed of individuals from various specialities.</td></tr><tr><td></td><td>IV. A team from the same department or functional area involved in efforts to improve work activities or to solve problems.</td></tr></table><p>Choose the correct answer from the options given below:</p><p class=\"small muted\">The table was an image in the paper; typed out here.</p>",
  opts: ["A-III, B-I, C-IV", "A-IV, B-I, C-III", "A-III, B-I, C-II", "A-II, B-IV, C-I"],
  ans: 2,
  why: ["False: C-IV is a functional (problem-solving) team.", "False: A-IV is a functional team.", "True: A-III, B-I, C-II.", "False: every pair is wrong."],
  sol: "<p>Various specialities → cross-functional (A-III). Technology links dispersed members → virtual (B-I). Takes on supervisory responsibilities → self-managed (C-II). IV (same department) is the functional team, a distractor.</p>",
  trap: "List 2 has one extra item (IV) that matches nothing." });
