PQ(SPG, '2023T1', 24, 1, 'mcq', { fam: "g-finstmt",
  cs: ["fin-statements"],
  week: 7,
  diff: "hard",
  q: "<p>Consider the following</p><p>1. A company increases its assets with debt.<br>2. A company decreases its debt by paying off loans with company cash.<br>3. A company increases its profit.</p><p>Which of the given above statement(s) will increase the owner’s equity net worth in the company?</p>",
  opts: ["1 only", "1 and 2 only", "3 only", "1 and 3 only"],
  ans: 2,
  why: ["Wrong: borrowing raises assets and liabilities equally; equity is unchanged.", "Wrong: paying off debt with cash lowers both sides equally.", "Correct: retained profit raises owner’s equity.", "Wrong: statement 1 leaves equity unchanged."],
  sol: "<p>Equity = assets − liabilities. (1) +asset, +liability → no change. (2) −asset, −liability → no change. (3) profit → equity rises. Answer: <b>3 only</b>.</p>",
  trap: "“Increases its assets” sounds like it must raise equity." });
